function modifierGroupsHtml(item, selections = state.modifiers[item.id] ?? {}, draft = false) {
  return (item.modifierGroups ?? []).map((group) => { const selected = selections[group.id] ?? []; const clearChoice = group.minSelections === 0 && group.maxSelections === 1 ? `<label class="modifier-option"><input type="radio" name="modifier-${e(item.id)}-${e(group.id)}" ${draft ? `data-menu-draft="${e(item.id)}"` : `data-modifier-item="${e(item.id)}"`} data-modifier-group="${e(group.id)}" value="" ${selected.length ? "" : "checked"}> <span>No selection</span></label>` : ""; return `<fieldset class="modifier-group"><legend>${e(group.name)} ${group.minSelections ? `<span class="badge">Required</span>` : `<span class="meta">Optional</span>`}</legend><p class="meta">Choose ${group.minSelections}${group.maxSelections !== group.minSelections ? `–${group.maxSelections}` : ""}</p>${clearChoice}${group.options.map((option) => { const chosen = selected.includes(option.id); const type = group.maxSelections === 1 ? "radio" : "checkbox"; return `<label class="modifier-option"><input type="${type}" name="modifier-${e(item.id)}-${e(group.id)}" ${draft ? `data-menu-draft="${e(item.id)}"` : `data-modifier-item="${e(item.id)}"`} data-modifier-group="${e(group.id)}" value="${e(option.id)}" ${chosen ? "checked" : ""} ${option.available ? "" : "disabled"}> <span>${e(option.name)} ${option.priceMinor ? `+${money(option.priceMinor)}` : ""}${option.available ? "" : " · unavailable"}</span></label>`; }).join("")}</fieldset>`; }).join("");
}
function selectedModifierNames(line) { return (line.modifiers ?? []).flatMap((selection) => { const group=line.modifierGroups?.find((candidate)=>candidate.id===selection.groupId); return selection.optionIds.map((id)=>group?.options.find((option)=>option.id===id)?.name).filter(Boolean); }); }

