  showDialog(`<div class="menu-item-sheet">${item.photoUrl ? `<img class="menu-detail-photo" src="${e(item.photoUrl)}" alt="${e(item.name)}">` : ""}<h2 id="dialog-title" tabindex="-1">${e(item.name)}</h2><strong>${money(item.priceMinor)}</strong><p>${e(item.description)}</p><p class="allergy">${item.allergens?.length ? `Contains ${item.allergens.map(e).join(", ")} · restaurant supplied` : "Allergens not listed. Ask the restaurant before ordering."}</p>${item.dietaryTags?.length ? `<p>${item.dietaryTags.map(e).join(" · ")}</p>` : ""}${item.energyKcal!=null||item.energyKj!=null?`<p class="meta">Per portion: ${item.energyKcal!=null?`${e(item.energyKcal)} kcal`:""}${item.energyKj!=null?` · ${e(item.energyKj)} kJ`:""} · restaurant supplied</p>`:""}${modifierGroupsHtml(item,menuItemDraft.selections,true)}<div class="qty"><button data-action="menu-item-quantity" data-delta="-1" aria-label="Decrease item quantity">−</button><span data-menu-draft-quantity>${menuItemDraft.quantity}</span><button data-action="menu-item-quantity" data-delta="1" aria-label="Increase item quantity">+</button></div><p class="form-error" data-menu-draft-error role="status"></p><button class="primary" data-action="menu-item-save">${state.cart[id] ? "Update basket" : "Add to basket"} · <span data-menu-draft-total></span></button></div>`);
  updateMenuDraft();
