async function authSubmit(form, register = false) {
  const data = Object.fromEntries(new FormData(form)); const button = form.querySelector(AUTH_SUBMIT_SELECTOR); button.disabled = true;
  try { const result = await api(`/api/auth/${register ? "register" : "login"}`, { method: "POST", body: JSON.stringify(data) }); const resumeCheckout = state.pendingCheckout && result.user.role === "customer"; resetIdentity(result.user);if(await resumeCustomerEmailLink())return; if (resumeCheckout) { state.pendingCheckout = false; renderCheckout(); } else await navigate(result.user.role === "customer" ? "discover" : "workspace"); }
  catch (error) { const box = form.querySelector(".form-error"); box.className = "form-error error"; box.textContent = error.message; button.disabled = false; }
}

async function demoLogin(role) {
  const credentials = { customer: ["customer@calai.local", "LocalCustomer!4310"], restaurant: ["restaurant@calai.local", "LocalRestaurant!4310"], admin: ["admin@calai.local", "LocalAdmin!4310"] }[role];
  try { const result = await api("/api/auth/login", { method: "POST", body: JSON.stringify({ email: credentials[0], password: credentials[1] }) }); const resumeCheckout = state.pendingCheckout && result.user.role === "customer"; resetIdentity(result.user);if(await resumeCustomerEmailLink())return; if (resumeCheckout) { state.pendingCheckout = false; renderCheckout(); } else await navigate(role === "customer" ? "discover" : "workspace"); } catch (error) { message(error.message); }
}

async function loadNotifications(){
  const generation=state.generation;
  try{const data=await api("/api/notifications");if(generation!==state.generation||!state.user)return;const fresh=state.seenNotificationIds?data.items.filter(item=>!state.seenNotificationIds.has(item.id)):[];if(state.soundEnabled&&state.user.role==="restaurant"&&state.view==="workspace"&&fresh.some(item=>["new_order","order_message"].includes(item.type)))playOrderSound();state.seenNotificationIds=new Set(data.items.map(item=>item.id));state.notifications=data.items.filter(item=>!item.readAt);state.unreadCount=data.unreadCount;if(state.user.role==="customer"){if(state.notificationsOpen&&fresh.some(item=>!item.readAt)){const dialog=document.querySelector("[data-dialog]");if(dialog&&!dialog.querySelector(".notification-incoming"))dialog.insertAdjacentHTML("beforeend",'<button class="secondary notification-incoming" data-action="notifications">New updates available — refresh notifications</button>');}notificationAlert.update(data.items);}setAccount();if(state.view==="messages")void state.inboxPanel?.refresh();if(state.openContact&&fresh.some(item=>state.openContact.support?item.supportCaseId===state.openContact.id:item.conversationId===state.openContact.id))void state.messagePanel?.refresh();}catch{/* Keep the current inbox state during a transient failure. */}
}
function showNotifications(){
  notificationAlert.acknowledge(state.notifications);saveNotificationAcknowledgements();
  showDialog(`<h2 id="dialog-title" tabindex="-1">Notifications</h2>${state.notifications.length?`<div class="notification-list">${state.notifications.map(n=>`<article class="notification ${n.readAt?"":"unread"}"><h3>${e(n.title)}</h3><p>${e(n.message)}</p><small>${date(n.createdAt)}${n.orderId?` · Order ${e(shortId(n.orderId))}`:""}</small><div class="card-actions">${n.readAt?"":`<button class="secondary" data-action="mark-notification" data-id="${e(n.id)}">Mark read</button>`}${n.supportCaseId?`<button class="primary" data-action="notification-support" data-id="${e(n.id)}" data-support="${e(n.supportCaseId)}">View request & reply</button>`:""}${n.conversationId?`<button class="primary" data-action="notification-conversation" data-id="${e(n.id)}" data-conversation="${e(n.conversationId)}">Open conversation</button>`:""}${n.orderId?`<button class="secondary" data-action="${n.type==="order_message"?"notification-message":"notification-order"}" data-id="${e(n.id)}" data-order="${e(n.orderId)}">${n.type==="order_message"?"Read order message":"Open order"}</button>`:""}${n.offerId?`<button class="secondary" data-action="notification-offer" data-id="${e(n.id)}" data-offer="${e(n.offerId)}">Open offer</button>`:""}</div></article>`).join("")}</div>`:`<div class="empty"><strong>You’re all caught up</strong><p>Order updates, messages and offers will appear here.</p></div>`}`);
  state.notificationsOpen=true;
}

async function loadOffers(pageIndex=0,quiet=false) {
  if(!quiet)loading("Loading offers");const generation=state.generation,navigation=state.navigationVersion,request=state.offerRequestVersion=(state.offerRequestVersion||0)+1,cursor=state.offerCursors?.[pageIndex];
  try{const response=await api('/api/offers?'+new URLSearchParams({limit:'20',scope:'active',...(cursor?{after:cursor}:{})}));if(generation!==state.generation||navigation!==state.navigationVersion||request!==state.offerRequestVersion||state.view!=="offers")return;state.offers=response.items;state.offerInboxItems=response.items;state.offerNextCursor=response.nextCursor;state.offerPageIndex=pageIndex;state.offerCursors=state.offerCursors||[null];renderOffers();if(!state.offerExpiryTimer)state.offerExpiryTimer=setInterval(()=>{if(generation===state.generation&&state.view==="offers"&&!document.hidden)renderOffers();},15000);}catch(error){if(generation===state.generation&&request===state.offerRequestVersion&&state.view==="offers"){if(quiet)message(error.message);else showError(error);}}
}
function renderOffers(){const page=state.offerPageIndex||0,html='<section class="section customer-offers-page"><header class="customer-offers-heading"><span class="eyebrow">Your next great meal</span><h1>Offers</h1><p>Current offers, personalised for you. Tap × to remove an offer from your account.</p></header>'+customerOffersHtml(state.offerInboxItems||[])+'<nav class="customer-offer-pagination" aria-label="Offer pages"><button class="secondary" data-action="offer-previous" '+(!page?'disabled':'')+'>Previous</button><span>Page '+(page+1)+' · Up to 20 offers</span><button class="secondary" data-action="offer-next" '+(!state.offerNextCursor?'disabled':'')+'>Next</button></nav></section>';if(main.querySelector('.customer-offers-page')&&state.offersRenderedHtml===html)return;state.offersRenderedHtml=html;main.innerHTML=html;}
async function dismissOffer(id,button){
  if(state.dismissingOffers?.has(id))return;const generation=state.generation,navigation=state.navigationVersion,wasSelected=state.selectedOffer?.id===id;state.dismissingOffers=state.dismissingOffers||new Set();state.dismissingOffers.add(id);if(button)button.disabled=true;
  try{await api('/api/offers/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({dismissed:true})});if(generation!==state.generation||navigation!==state.navigationVersion)return;state.offers=state.offers.filter(offer=>offer.id!==id);state.offerInboxItems=(state.offerInboxItems||[]).filter(offer=>offer.id!==id);if(wasSelected)state.selectedOffer=null;closeDialog();renderOffers();message(wasSelected?'Offer removed from your account and basket. Your basket items are unchanged.':'Offer removed from your account.');await loadOffers(state.offerPageIndex||0,true);await loadNotifications();}catch(error){if(generation===state.generation){message(error.message);if(button?.isConnected)button.disabled=false;}}finally{state.dismissingOffers?.delete(id);}
}
async function chooseOffer(id) {
  const offer = state.offers.find((entry) => entry.id === id); if (!offer) return;
  try { await api(`/api/offers/${encodeURIComponent(id)}`, { method:"PATCH", body:JSON.stringify({ viewed:true }) }); state.selectedOffer = offer;if(offer.campaignType==="free_delivery"){state.fulfillment="delivery";state.fulfillmentExplicit=true;} await openMenu(offer.restaurantId); message(`Offer selected: ${promotionBadge(offer)}. Minimum food basket ${money(offer.minSubtotalMinor)}.`); } catch(error) { message(error.message); }
}

