  try{const controller=await mountCustomerInbox({api,container,openThread:(id,title)=>void showCustomerContact(id,false,title)});if(generation!==state.generation||navigation!==state.navigationVersion||state.view!=="messages"){controller.close();return;}state.inboxPanel=controller;}catch(error){if(generation===state.generation&&state.view==="messages")showError(error);}
