document.addEventListener("keydown", (event) => { const dialog=document.querySelector("[data-dialog]"); if (event.key === "Escape" && dialog) { closeDialog(); return; } if (event.key === "Tab" && dialog) { const focusable=[...dialog.querySelectorAll("button,input,select,textarea,a[href]")].filter((node)=>!node.disabled&&node.getClientRects().length>0); if (!focusable.length) return; const first=focusable[0], last=focusable.at(-1); if (event.shiftKey && document.activeElement===first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement===last) { event.preventDefault(); first.focus(); } } });
