function checkoutQuoteBody(){const data=checkoutFormValues(document.querySelector("#checkout-form"));return{restaurantId:state.selected.id,items:orderItemPayload(cartLines(state.menu,state.cart,state.modifiers)),fulfillment:state.fulfillment,autoApplyOffers:true,...(state.fulfillment==="delivery"?{deliveryAddress:{line1:data.get("line1"),...(data.get("line2")?{line2:data.get("line2")}:{}),city:data.get("city"),postcode:data.get("postcode")}}:{})};}
async function showOrderConversation(orderId){closeDialog();showDialog('<h2 id="dialog-title" tabindex="-1">Message restaurant</h2><div id="order-message-panel"></div>');const generation=state.generation,token=Symbol("order-contact"),container=document.querySelector("#order-message-panel");state.contactToken=token;try{const controller=await openOrderMessaging({api,orderId,container,onClose:()=>{if(state.contactToken===token)closeDialog();}});if(generation!==state.generation||state.contactToken!==token||!container.isConnected){controller.close();return;}state.messagePanel=controller;}catch(error){if(container.isConnected&&generation===state.generation)container.textContent=error.message;}}
window.addEventListener("cal-eats-notifications-read",()=>{if(state.user)void loadNotifications();});

function readNotificationAcknowledgements(){try{return JSON.parse(sessionStorage.getItem('calai-notification-opened:'+state.user?.id)||'[]');}catch{return [];}}
function readCustomerSoundPreference(){try{return localStorage.getItem("cal-eats-customer-sound:"+state.user?.id)!=="off";}catch{return true;}}
function saveNotificationAcknowledgements(){try{sessionStorage.setItem('calai-notification-opened:'+state.user?.id,JSON.stringify(notificationAlert.acknowledgedIds()));}catch{}}
function stopCustomerNotificationSound(){for(const node of customerAudioNodes){try{node.stop();}catch{}}customerAudioNodes.clear();}
function playCustomerNotificationSound(){const context=state.soundContext;if(state.user?.role!=='customer'||!context||context.state!=='running'||document.hidden)return;for(const [index,frequency] of [784,1046,880].entries()){const osc=context.createOscillator(),gain=context.createGain(),at=context.currentTime+index*.19;osc.type='sine';osc.frequency.value=frequency;gain.gain.setValueAtTime(.001,at);gain.gain.exponentialRampToValueAtTime(.055,at+.02);gain.gain.exponentialRampToValueAtTime(.001,at+.16);osc.connect(gain).connect(context.destination);customerAudioNodes.add(osc);osc.onended=()=>{customerAudioNodes.delete(osc);osc.disconnect();gain.disconnect();};osc.start(at);osc.stop(at+.18);}}
async function ensureCustomerNotificationSound(){if(state.user?.role!=='customer'||!notificationAlert.snapshot().soundEnabled)return;const generation=state.generation;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;state.soundContext??=new Audio();await state.soundContext.resume();if(generation===state.generation)renderCustomerNotificationPrompt();}catch{if(generation===state.generation)renderCustomerNotificationPrompt();}}
function renderCustomerNotificationPrompt(){const box=document.querySelector('#notification-prompt');if(!box)return;const snapshot=notificationAlert.snapshot(),pending=state.user?.role==='customer'&&snapshot.pending>0;document.querySelector('.notification-bell')?.classList.toggle('needs-attention',pending);if(!pending){box.hidden=true;box.innerHTML='';stopCustomerNotificationSound();return;}box.hidden=false;if(!box.querySelector('[data-action="notifications"]'))box.innerHTML='<div><strong>You have new updates</strong><span>Open your notifications to catch up.</span></div><button data-action="notifications" class="primary">Open notifications</button>';}
document.addEventListener('pointerdown',event=>{if(event.isTrusted&&state.user?.role==='customer'&&state.soundContext?.state!=='running')void ensureCustomerNotificationSound().then(()=>notificationAlert.resume());},{capture:true});
document.addEventListener('keydown',event=>{if(event.isTrusted&&state.user?.role==='customer'&&state.soundContext?.state!=='running')void ensureCustomerNotificationSound().then(()=>notificationAlert.resume());},{capture:true});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopCustomerNotificationSound();else notificationAlert.resume();});
